function pickEncoding(type, size, opts = {}) {
  const n = Number(size)
  if (!Number.isFinite(n) || n < 0) throw new Error('size 必须是非负有限数字：' + size)

  switch (type) {
    case 'string':
      if (opts.integer && n <= ENCODING_LIMITS.stringInt) return 'int'
      return n <= ENCODING_LIMITS.stringEmbstr ? 'embstr' : 'raw'
