/**
 * 空值的哨兵：缓存里放一个不可能等于业务值的标记，
 * 用来区分「没缓存过」（undefined）和「缓存过、结果是空」。
 */
const NULL_MARK = '__LF_NULL__'

/**
 * 极简缓存后端，模拟 Redis 的 get / set(EX) / del。
 * 这里只记 TTL 数值，真正的过期机制在第 1 关已经写过了。
 */
class MemoryCache {
  constructor() {
