    same(store.get('job', 5001), 'B')
    same(store.delIfValue('job', 'A', 5001), false, 'A 拿着过期租约来释放，删不掉 B 的锁')
    same(store.get('job', 5001), 'B', 'A 以为自己还持有锁 —— 这就是 Redlock 保证不了的东西')
