// 1) 分片：key → 槽 → 节点
const cluster = new Cluster(['A', 'B', 'C'])
hashSlot('foo')                    // 12182
cluster.set('user:1', 'alice')
cluster.nodeOf('user:1')           // 属主节点
cluster.route('A', 'user:1')       // 可能返回 MOVED

// 2) hash tag：两个 key 强制同槽，才能一起做 MGET / 事务
hashSlot('{u1}.name') === hashSlot('{u1}.email')   // true

// 3) 迁移一个槽
